files={f:open(f,encoding='utf-8').read() for f in glob.glob('src/p*.txt')}
for a,b in R:
    hit=[f for f,t in files.items() if a in t]
    if not hit:
        # try without leading capital
        a2=a[0].lower()+a[1:]; b2=b[0].lower()+b[1:]
        hit=[f for f,t in files.items() if a2 in t]
        if hit: a,b=a2,b2
    if not hit: print('MISS',a[:70]); continue
    for f in hit: files[f]=files[f].replace(a,b,1)
for f,t in files.items(): open(f,'w',encoding='utf-8').write(t)
